def minimum_xy_swaps(s1, s2):
 x=sum(a!=b and a=='x' for a,b in zip(s1,s2));y=sum(a!=b and a=='y' for a,b in zip(s1,s2))
 return -1 if (x+y)%2 else x//2+y//2+2*(x%2)

